public class GifEncoderHelper {

	private boolean interlace = false;

	private int width, height;

	private byte[] pixels;

	private byte[] r, g, b; // the color look-up table

	private int pixelIndex;

	private int numPixels;

	private int transparentPixel = -1; // hpm

	/**
	 * Constructs a new GifEncoder.
	 * @param width The image width.
	 * @param height The image height.
	 * @param pixels The pixel data.
	 * @param r The red look-up table.
	 * @param g The green look-up table.
	 * @param b The blue look-up table.
	 */
	public GifEncoderHelper(int width, int height, byte[] pixels, byte[] r, byte[] g, byte[] b) {
		this.width = width;
		this.height = height;
		this.pixels = pixels;
		this.r = r;
		this.g = g;
		this.b = b;
		interlace = false;
		pixelIndex = 0;
		numPixels = width * height;
	}

	/**
	 * Constructs a new GifEncoder using an 8-bit AWT Image. The image is
	 * assumed to be fully loaded.
	 */
	public GifEncoderHelper(Image img) {
		width = img.getWidth(null);
		height = img.getHeight(null);
		pixels = new byte[width * height];
		PixelGrabber pg = new PixelGrabber(img, 0, 0, width, height, false);

		try {
			pg.grabPixels();
		} catch (InterruptedException e) {
			System.err.println(e);
		}
		;
		ColorModel cm = pg.getColorModel();

		if (cm instanceof IndexColorModel) {
			pixels = (byte[]) (pg.getPixels());
			// hpm
			IndexColorModel icm = (IndexColorModel) cm;

			setTransparentPixel(icm.getTransparentPixel());
		} else {
			throw new IllegalArgumentException("Image must be 8-bit");
		}
		IndexColorModel m = (IndexColorModel) cm;
		int mapSize = m.getMapSize();

		r = new byte[mapSize];
		g = new byte[mapSize];
		b = new byte[mapSize];
		m.getReds(r);
		m.getGreens(g);
		m.getBlues(b);
		interlace = false;
		pixelIndex = 0;
		numPixels = width * height;

	}

	/** Saves the image as a GIF file. */
	public void write(OutputStream out) throws IOException {
		// Figure out how many bits to use.
		int numColors = r.length;
		int BitsPerPixel;

		if (numColors <= 2) {
			BitsPerPixel = 1;
		} else if (numColors <= 4) {
			BitsPerPixel = 2;
		} else if (numColors <= 16) {
			BitsPerPixel = 4;
		} else {
			BitsPerPixel = 8;
		}

		int ColorMapSize = 1 << BitsPerPixel;
		byte[] reds = new byte[ColorMapSize];
		byte[] grns = new byte[ColorMapSize];
		byte[] blus = new byte[ColorMapSize];

		for (int i = 0; i < numColors; i++) {
			reds[i] = r[i];
			grns[i] = g[i];
			blus[i] = b[i];
		}

		// hpm
		GIFEncode(out, width, height, interlace, (byte) 0, getTransparentPixel(), BitsPerPixel, reds, grns, blus);
	}

	// hpm
	public void setTransparentPixel(int pixel) {
		transparentPixel = pixel;
	}

	// hpm
	public int getTransparentPixel() {
		return transparentPixel;
	}

	static void writeString(OutputStream out, String str) throws IOException {
		byte[] buf = str.getBytes();

		out.write(buf);
	}

