		try (Trx trx = ContentNodeHelper.trx()) {
			Transaction t = TransactionManager.getCurrentTransaction();
			Node node = getNode(nodeId, ObjectPermission.edit);
			try (ChannelTrx cTrx = new ChannelTrx(node)) {
