			return new LegacyFolderListResponse(new Message(Type.CRITICAL, e.getLocalizedMessage()), new ResponseInfo(ResponseCode.NOTFOUND, e.getLocalizedMessage()));
		} catch (InsufficientPrivilegesException e) {
