			long[] times = mytestSpecificCachePerformance(dsRule);

			logger.info("Times[0]: " + times[0]);
			logger.info("Times[1]: " + times[1]);
			if (mintimes == null) {
				mintimes = times;
			} else {
				if (mintimes[0] > times[0]) {
					mintimes[0] = times[0];
				}
				if (mintimes[1] > times[1]) {
					mintimes[1] = times[1];
				}
			}
		}
