	/**
	 * clear the cache of the factory.
	 */
	public void clearLocal() throws NodeException {
		if (cache != null) {
			try {
				cache.clear();
			} catch (PortalCacheException e) {
				throw new NodeException("Error while clearing the factory caches", e);
			}
		}
		typeCaches.values().forEach(cache -> {
			try {
				cache.clear();
			} catch (PortalCacheException e) {
			}
		});
	}

