		}
		if (cr.getProjectPerNode() != null) {
			nodeCR.setProjectPerNode(cr.getProjectPerNode());
		}
		if (cr.getVersion() != null) {
			nodeCR.setVersion(cr.getVersion());
		}
		return nodeCR;
